var e=(e=[])=>[...new Set(e.filter(Boolean))],t=e=>({documented:`high`,public:`high`,witnessed:`medium`,"people-only":`medium`,disputed:`low`,rumor:`low`,unknown:`unknown`,lost:`low`,unrecorded:`unknown`,secret:`unknown`})[e]??`medium`,n=({overview:e,evidence:n,gap:r,dispute:i,cultural:a,sources:o,importance:s,image:c,knowledgeStatus:l=`documented`,chronology:u=[]})=>({description:`${e} ${n} ${r}`,archivalOverview:e,provenance:n,publicKnowledge:[n],knowledgeGaps:[r],culturalReadings:[a],historicalSources:o,disputedClaims:[i],narrativeImportance:s,imageBrief:c,knowledgeStatus:{witnessed:`documented`,prophetic:`disputed`,redacted:`secret`}[l]??l,confidence:t(l),detailedTimeline:u.map(([e,t,n])=>({date:e,title:t,description:n})),sections:[{title:`Registro preservado`,body:e},{title:`Base documental`,body:n},{title:`Limite do conhecimento`,body:r},{title:`Leituras em conflito`,body:`${i} ${a}`}]});function r(t,n){return t.map(t=>{let r=n[t.id];return r?{...t,...r,events:e([...t.events??[],...r.events??[]]),historicalSources:e([...t.historicalSources??[],...r.historicalSources??[]]),disputedClaims:e([...t.disputedClaims??[],...r.disputedClaims??[]]),relations:e([...t.relations??[],...r.relations??[]].map(e=>JSON.stringify(e))).map(e=>JSON.parse(e))}:t})}var i={vyrasul:n({overview:`Vyrasul é tratado pelo Arquivo como um animal raro, inteligente e territorial, não como soberano, divindade ou membro das forças de Winterfeld. Marcas nas geleiras mostram ciclos de caça, repouso e defesa de área que não acompanham calendários humanos.`,evidence:`Avistamentos de gigantes, caçadores e vigias concordam sobre escamas brancas, sopro que retira calor e recusa de aproximação a povoados. Ferimentos antigos e o auxílio recebido no norte são conhecidos por testemunho convergente.`,gap:`Origem, idade, sexo, reprodução e motivo exato de sua permanência continuam desconhecidos. Nenhuma pessoa fala em nome do dragão, e toda alegação de pacto político é baseada em rumor.`,dispute:`Devotos da Última Brasa o chamam de emissário; naturalistas e o concílio rejeitam essa leitura.`,cultural:`Gigantes o descrevem como vizinho perigoso; jarls o usam como símbolo sem possuir autoridade sobre ele.`,sources:[`Cantos do Degelo`,`Diários de vigias de Winterheim`,`Rastros medidos nas geleiras`],importance:`Delimita a diferença entre convivência ecológica e apropriação política de uma criatura extraordinária.`,image:`Dragão branco naturalista em geleira vasta, sem coroa, arquitetura, exército ou iconografia de governo.`,knowledgeStatus:`witnessed`,chronology:[[`Era das Coroas`,`Primeiros registros convergentes`,`Gigantes encontram Vyrasul ferido e comunidades suspendem a caça na área.`],[`1204 d.C.`,`Presença atual`,`Rastros recentes confirmam permanência nas geleiras sem vínculo com a coroa.`]]}),alcarion:n({overview:`Alcarion foi um dragão costeiro observado sobre ilhas vazias e águas profundas. Seus trajetos seguiam cardumes e correntes, razão pela qual pilotos de Eldemar o registravam junto a marés, e não junto a fronteiras políticas.`,evidence:`Livros de bordo separados descrevem escamas escuras com reflexo verde, pouso em rocha nua e alimentação por grandes peixes. O último avistamento autenticado ocorreu sobre o Mar das Estrelas há mais de um século.`,gap:`Seu destino é desconhecido: morte, migração, Fratura ou erro de rota permanecem hipóteses. Supostos ovos, ossos e mensagens atribuídas ao dragão nunca foram autenticados.`,dispute:`Cartógrafos relacionam o desaparecimento a uma anomalia marítima; capitães consideram coincidência.`,cultural:`Eldemar o lembra como medida da vastidão do mar, enquanto contrabandistas vendem falsos mapas de ninho.`,sources:[`Livros de bordo de Eldemar`,`Registros de pilotos do Arquipélago`,`Catálogo de falsificações dracônicas`],importance:`Liga história natural, navegação e incerteza sobre o Mar das Estrelas sem criar uma civilização dracônica.`,image:`Dragão costeiro escuro sobre mar aberto, anatomia animal e escala dada por ilhas e navio distante.`,knowledgeStatus:`lost`,chronology:[[`Século XI`,`Rotas costeiras`,`Pilotos registram passagens sazonais de Alcarion.`],[`Último registro conhecido`,`Desaparecimento`,`O dragão cruza uma anomalia sobre o Mar das Estrelas e não volta a ser autenticado.`]]}),mhazir:n({overview:`Mhazir era o dragão de cobre associado às terras áridas, reconhecível por uma cicatriz que alterava o movimento da asa direita. Caçava grandes herbívoros e evitava concentrações humanas, comportamento incompatível com relatos de comando imperial.`,evidence:`Rastreadores do deserto, vigias Bellatrix e duas caravanas independentes registraram a mesma anatomia e direção de voo. A última rota confirmada atravessou as Montanhas Cinzentas durante a Caça às Bruxas.`,gap:`Nenhuma fonte pública determina se prosseguiu para além do mapa, morreu ou mudou de território. Fragmentos vendidos como escamas provaram ser cobre comum.`,dispute:`Canções tardias o colocam à frente de exércitos; não existe assentamento, tributo ou testemunho que sustente a versão.`,cultural:`Povos de Zharak leem sua passagem como migração animal; cronistas cortesãos a transformaram em presságio.`,sources:[`Cadernos de rastreadores de Zharak`,`Atas Bellatrix`,`Laudos minerais de Kar-Dûm`],importance:`Expõe como propaganda transforma fauna rara em ameaça política durante perseguições.`,image:`Dragão de cobre com asa cicatrizada sobre planalto árido, sem equipamentos ou sinais de sociedade.`,knowledgeStatus:`lost`,chronology:[[`Antes de 613 d.C.`,`Território árido`,`Rastreadores documentam hábitos de caça e repouso.`],[`Caça às Bruxas`,`Última travessia`,`Mhazir cruza as Montanhas Cinzentas e desaparece do registro conhecido.`]]}),"grifo-das-alturas":n({overview:`Grifos das Alturas são predadores de penhasco que formam pares sazonais e defendem ninhos por som, voo rasante e queda de pedras.`,evidence:`Pastores e naturalistas registram rotas de ninho, restos de alimentação e resposta previsível a sinos agudos. Nenhuma sela compatível ou tradição de domesticação foi comprovada.`,gap:`A população total não é registrada, e ninhos remotos permanecem desconhecidos para evitar caça de troféus.`,dispute:`Baladas militares descrevem cavalaria de grifos; arquivos de campanha tratam a imagem como alegoria.`,cultural:`Pastores protegem rebanhos com cobertura; nobres usam penas encontradas como insígnia sem vínculo com a espécie.`,sources:[`Calendários de pastoreio`,`Cadernos de naturalistas das Montanhas`,`Inventários de campanha`],importance:`Torna o bestiário parte da economia de montanha e corrige a fantasia de montaria sem fundamento.`,image:`Grifo anatomicamente plausível no ninho, com pastores minúsculos ao fundo para escala.`,knowledgeStatus:`documented`}),"hidra-dos-pantanos":n({overview:`A Hidra dos Pântanos é um grande réptil de pescoços múltiplos cuja regeneração consome massa corporal em vez de produzir cabeças infinitas.`,evidence:`Caçadores mediram perda de peso, alteração de apetite e cicatrização após ferimentos. Trilhas confirmam que indivíduos procuram águas rasas com muita presa.`,gap:`Não há censo confiável nem acordo sobre idade máxima; ovos atribuídos à espécie permanecem não registrados.`,dispute:`Mercenários defendem fogo como solução, enquanto guardiões mostram que incêndios de turfa causam dano regional maior.`,cultural:`Comunidades meridionais preferem condução por iscas e fechamento temporário de canais.`,sources:[`Relatórios de caça meridional`,`Mapas de turfa`,`Registros de perda de rebanhos`],importance:`Apresenta um conflito em que conhecimento ecológico é mais eficaz que heroísmo destrutivo.`,image:`Réptil pesado em pântano raso, pescoços biologicamente articulados e vegetação úmida não incendiada.`,knowledgeStatus:`witnessed`}),"kraken-de-eldemar":n({overview:`O nome Kraken de Eldemar reúne avistamentos de um cefalópode colossal nas rotas profundas ao sul. O Arquivo não presume que todos pertençam ao mesmo indivíduo.`,evidence:`Marcas de ventosa, danos de casco e mudanças de cardume coincidem com correntes frias. Protocolos de silêncio do casco reduzem encontros segundo séries portuárias.`,gap:`Quantidade, reprodução, profundidade de abrigo e longevidade são desconhecidas; nenhum corpo completo foi recuperado.`,dispute:`Guildas preferem um único monstro nomeável, enquanto naturalistas falam em população rara.`,cultural:`Sinos de casco são desligados por prudência, e histórias de tributo marítimo são rejeitadas por capitães.`,sources:[`Laudos de casco`,`Livros de maré`,`Depoimentos de pilotos`],importance:`Transforma risco marítimo em conhecimento acumulado, seguro de carga e disputa sobre rotas.`,image:`Tentáculos sob navio de madeira visto em corte de onda, sem rosto humanoide ou adereços.`,knowledgeStatus:`witnessed`}),"cervo-do-nevoeiro":n({overview:`O Cervo do Nevoeiro é herbívoro protegido cuja pelagem translúcida, marcha silenciosa e escolha de clareiras produzem a impressão de desaparecimento.`,evidence:`Pelos examinados por artesãos de Sylvaris refratam tons do ambiente sem sinal de magia. Migrações coincidem com fungos, qualidade da água e abertura de brotos.`,gap:`Locais de parto não são publicados e o tamanho da população é conhecido apenas pelos guardiões de bosque.`,dispute:`Visitantes alegam teletransporte; observações continuadas mostram deslocamento comum oculto pela névoa.`,cultural:`Elfos o usam como indicador ecológico, jamais como mensageiro divino obrigatório.`,sources:[`Cadernos de sentinelas`,`Amostras de pelo caído`,`Calendários de clareiras`],importance:`Demonstra que maravilha natural não precisa ser convertida em magia hereditária.`,image:`Grande cervo de pelagem translúcida em bosque úmido, camuflagem óptica natural e sem brilho arcano.`,knowledgeStatus:`people-only`}),"lobo-de-vidro":n({overview:`Lobos de Vidro são canídeos adaptados às salinas, com pelos endurecidos por depósitos minerais que tilintam durante a corrida.`,evidence:`Rastreadores observam caça contra o vento, formação de bandos e busca de caravanas debilitadas. A remoção dos sais abre feridas e não produz material valioso.`,gap:`Rotas de criação e mortalidade em anos de seca permanecem não registradas fora dos poços de Zharak.`,dispute:`Mercadores afirmam que o pelo vira cristal encantado; análises mostram sal, queratina e poeira.`,cultural:`Caçadores responsáveis afastam bandos com fogo controlado e deixam água longe das estradas.`,sources:[`Registros dos poços`,`Laudos de Kar-Dûm`,`Diários de caravanas`],importance:`Integra fauna, clima e ética de estrada nas regiões áridas.`,image:`Canídeo de pelos mineralizados em salina noturna, anatomia realista e reflexo discreto.`,knowledgeStatus:`documented`}),"vigia-de-pedra":n({overview:`O Vigia de Pedra é uma colônia subterrânea de pequenos organismos que produz carapaça mineral comum e reage coletivamente a vibrações.`,evidence:`Mineiros anões acompanharam crescimento, alimentação por películas minerais e fechamento defensivo. Batidas ritmadas anunciam passagem sem destruir a colônia.`,gap:`O ciclo reprodutivo e a comunicação interna são conhecidos apenas parcialmente pelos salões mais profundos.`,dispute:`Estrangeiros o chamam de estátua desperta; estudos de Kar-Dûm rejeitam construto ou feitiço.`,cultural:`Anões incluem a espécie em protocolos de escavação, pois seu fechamento pode salvar ou bloquear um túnel.`,sources:[`Placas dos Nove Ecos`,`Relatórios de escavação`,`Desenhos de colônias`],importance:`Mostra como conhecimento anão combina trabalho, segurança e respeito por vida não humanoide.`,image:`Colônia mineral em parede de caverna, parcialmente aberta diante de anões que batem ferramentas em ritmo.`,knowledgeStatus:`people-only`})},a={"o-ultimo-bruxo":n({overview:`O primeiro volume é registrado como narrativa em desenvolvimento, não como crônica já ocorrida. Seu eixo é a escolha de Sirius ao deixar o isolamento, enfrentar versões incompatíveis dos pais e conhecer Elara antes de ambos compreenderem o pacto.`,evidence:`Sinopses editoriais e cenas consolidadas confirmam baú, carta, Fulgarion, encontro e partida. Eventos posteriores continuam sujeitos ao desenvolvimento do manuscrito.`,gap:`Desfecho, ordem final de capítulos e destinos além dos marcos canônicos estão não registrados.`,dispute:`Leitores internos divergem entre uma história de herança e uma história de recusa da herança; ambas permanecem leituras.`,cultural:`O volume contrapõe arquivo heroico, memória familiar e propaganda das coroas.`,sources:[`Plano narrativo do Volume I`,`Dossiês de Sirius e Elara`,`Linha do tempo de 1204`],importance:`Abre a saga e ensina o leitor a distinguir cânone histórico, memória parcial e escolha presente.`,image:`Capa 2:3 com Sirius diante do baú e tempestade contida, área segura para título sem letras geradas.`,knowledgeStatus:`documented`}),"a-carta-e-a-tempestade":n({overview:`O segundo volume permanece planejado. A cifra Bellatrix funciona como investigação logística: distâncias, estoques e passagens importam tanto quanto as revelações sobre a perseguição.`,evidence:`O plano editorial confirma deslocamento rumo às Montanhas Cinzentas, pressão de Ravenhold e busca pela Fortaleza do Véu.`,gap:`Nenhuma sobrevivência Nimbus ou Rivs é declarada como fato pelo registro do livro; pistas futuras permanecem abertas e não registradas.`,dispute:`Facções da história interpretarão a viagem como ameaça militar, embora seu objetivo seja documental e pessoal.`,cultural:`A jornada confronta a monumentalização de Normus com o trabalho humano de Namídia e dos vigias.`,sources:[`Plano narrativo do Volume II`,`Cifras Bellatrix públicas`,`Atlas das rotas conhecidas`],importance:`Expande a saga para política de fronteira e restitui agência histórica às redes civis.`,image:`Capa 2:3 com estrada de montanha, carta cifrada e nuvens de tempestade ao longe, sem revelar personagens secretos.`,knowledgeStatus:`unrecorded`}),"cronicas-perdidas-de-sylvaris":n({overview:`As Crônicas Perdidas são uma edição pública comentada de testemunhos preservados pelos Círculos, com nomes vulneráveis omitidos e decisões da corte mantidas em contexto.`,evidence:`Colofões, diferenças de tinta e atas de custódia confirmam múltiplos escribas durante a Caça às Bruxas.`,gap:`A versão integral não é publicada; nomes protegidos, rotas e anexos reservados não fazem parte do bundle público.`,dispute:`Críticos chamam as omissões de censura; guardiões respondem que acesso histórico não autoriza expor pessoas.`,cultural:`Sylvaris lê o livro em jardins memoriais; reinos humanos o usam em debates de reparação.`,sources:[`Edição comentada pública`,`Atas dos Círculos`,`Catálogo de variantes`],importance:`Materializa o conflito entre preservação, privacidade e responsabilidade histórica.`,image:`Códice élfico gasto sobre mesa viva, trechos redigidos visíveis sem texto legível.`,knowledgeStatus:`redacted`}),"atlas-das-sete-rotas":n({overview:`O Atlas das Sete Rotas é manual de viagem renovado por edição, com distâncias expressas em tempo, estação, carga e risco. Não substitui a carta política oficial de Avernor.`,evidence:`Pedágios, pontes, níveis de rio e registros de pouso permitem comparar trajetos históricos e atuais.`,gap:`Rotas de evacuação, atalhos militares e caminhos recolhidos de Sylvaris são omitidos ou conhecidos apenas pelos povos responsáveis.`,dispute:`Mercadores acusam Eldemar de favorecer portos; editores demonstram que cada edição registra seus informantes.`,cultural:`Valoria lê em dias de carro; anões, em turnos de carga; marinheiros, em marés.`,sources:[`Edições anuais preservadas`,`Livros de pedágio`,`Diários de pilotos e carroceiros`],importance:`Sustenta o futuro cálculo de viagem e transforma geografia em experiência política e material.`,image:`Livro-atlas aberto com estrada, rio e rosa dos ventos, sem competir com o mapa canônico.`,knowledgeStatus:`documented`}),"tratado-das-linhagens":n({overview:`O Tratado das Linhagens separa magia hereditária, técnicas rúnicas, propriedades de artefatos e práticas religiosas. Sua tese central impede que treinamento comum seja confundido com o dom das três Casas.`,evidence:`Fragmentos Rivs concordam com registros Kayler, Nimbus e observações de artefatos usados por pessoas sem magia.`,gap:`Capítulos sobre transmissão hereditária foram perdidos; não há método público para prever manifestação individual.`,dispute:`Cortes tentaram usar o tratado como manual de registro racial, finalidade rejeitada nos comentários preservados.`,cultural:`Curadores, artífices e sacerdotes o citam para defender seus ofícios contra acusações de feitiçaria.`,sources:[`Fragmentos do Arquivo Rivs`,`Comentários de Kar-Dûm`,`Cópia de Sylvaris`],importance:`Fixa a regra canônica de magia sem transformar hereditariedade em justificativa de perseguição.`,image:`Tratado antigo com diagramas abstratos de três correntes, sem fórmulas de escola mágica.`,knowledgeStatus:`lost`}),"caderno-de-namidia":n({overview:`O Caderno de Namídia é simultaneamente livro de abastecimento e testemunho de uma rede civil. Sua leitura pública valoriza postos, animais, comida e pessoas comuns em vez de reduzir a resistência a um único herói.`,evidence:`Totais de grão correspondem a deslocamentos documentados; variações de coluna comprovam uso de cifra Bellatrix.`,gap:`Partes do caderno e a chave completa não estão disponíveis. O Arquivo não publica interpretações que possam indicar rotas ainda sensíveis.`,dispute:`Alguns cronistas tratam cada número como código; administradores lembram que grande parte é contabilidade literal.`,cultural:`Vigias o estudam como ética de abrigo, e historiadores como fonte sobre trabalho invisibilizado.`,sources:[`Folhas públicas do caderno`,`Inventários da Fortaleza do Véu`,`Atas da Mesa de Vigias`],importance:`Devolve a Namídia papel de autora logística e política, não simples companheira de Normus.`,image:`Caderno gasto, chaves, sacos de grão e marcas de inventário, sem expor cifras legíveis.`,knowledgeStatus:`redacted`})},o={"noite-das-doze-adagas":n({overview:`A morte de Marcellus Veyron é histórica; a simultaneidade de doze golpes e o destino uniforme dos conspiradores pertencem à tradição política.`,evidence:`Registros médicos indicam menos ferimentos do que a lenda, enquanto atas confirmam a participação de doze comandantes no rompimento do regime.`,gap:`A ordem dos golpes, nomes completos e localização das armas continuam perdidos.`,dispute:`Monarquistas chamam o ato de assassinato; arquivos regionais o descrevem como encerramento de tirania.`,cultural:`Cada reino reivindicou um herói entre os doze, tornando a memória instrumento de legitimidade.`,sources:[`Laudo médico fragmentário`,`Atas militares de 158`,`Baladas regionais`],importance:`Encerra a Queda da Coroa e demonstra como um fato produz memórias políticas incompatíveis.`,image:`Salão após o regicídio, doze sombras sugeridas e número real de feridas deliberadamente ambíguo.`,knowledgeStatus:`disputed`}),"arquivo-submerso":n({overview:`O Arquivo Submerso reúne indícios de depósitos Rivs em ilhas fluviais e uma leitura popular que os coloca sob águas permanentes.`,evidence:`Mapas de comporta e listas de caixa confirmam arquivos distribuídos; nenhum mapa autentica biblioteca submarina acessível por sangue.`,gap:`Destino dos registros centrais e funcionamento das instruções hidráulicas permanecem desconhecidos.`,dispute:`Caçadores leem “águas que recuam” como magia; engenheiros Rivs e anões a leem como operação de comportas.`,cultural:`Comunidades ribeirinhas protegem ruínas contra saque mesmo sem aceitar a lenda literal.`,sources:[`Mapas Rivs incompletos`,`Inventários de caixas`,`Relatos de ilhas fluviais`],importance:`Preserva a possibilidade documental dos Rivs sem afirmar sobreviventes ou acesso mágico secreto.`,image:`Ruína de arquivo em ilha durante vazante, mecanismos hidráulicos e ausência de figuras identificáveis.`,knowledgeStatus:`rumor`}),"pacto-dos-descendentes":n({overview:`O pacto entre Normus e Aelwen existiu, protegeu Sirius e permanece relevante para a relação entre os herdeiros. Ele não constitui casamento, propriedade ou renúncia ao consentimento.`,evidence:`O medalhão dividido, atas limitadas dos Círculos e ações de abrigo confirmam a existência do acordo.`,gap:`Alcance, cláusulas, contrapartidas e condições integrais são secretas e não aparecem no conteúdo público.`,dispute:`Canções românticas o transformam em união predestinada; nenhum fragmento autêntico sustenta essa leitura.`,cultural:`Sylvaris o debate como dever de proteção; inimigos o apresentam como conspiração dinástica.`,sources:[`Medalhão da Folha Partida`,`Atas públicas dos Círculos`,`Carta de Normus — existência confirmada`],importance:`Cria tensão entre proteção herdada e escolha pessoal sem revelar o mecanismo reservado.`,image:`Duas metades de medalhão diante de mãos separadas, sem casamento ou texto legível.`,knowledgeStatus:`secret`}),"sinos-do-mar-de-cinzas":n({overview:`Os sinos sob o Mar de Cinzas são um fenômeno acústico observado antes de nevoeiros que afetam bússolas e referências de costa.`,evidence:`Pilotos de embarcações diferentes registraram som grave, corrente ascendente e perda de orientação; protocolos de vela reduziram naufrágios.`,gap:`Origem exata do som e identidade do navio que retornou vazio não foram registradas de modo conclusivo.`,dispute:`Naturalistas propõem rochas ocas; marinheiros falam em torre afundada e mortos sem nome.`,cultural:`Eldemar trata o som como alerta operacional mesmo sem resolver sua natureza.`,sources:[`Livros de bordo`,`Carta de risco do Mar de Cinzas`,`Depoimentos de pilotos`],importance:`Mostra como uma lenda pode produzir prática segura sem ser declarada verdade sobrenatural.`,image:`Mar cinzento coberto de névoa, boias inclinadas e ondas sugerindo cavidades abaixo.`,knowledgeStatus:`witnessed`})},s={"o-veu":n({overview:`O Véu é o nome dado a descontinuidades verificáveis entre matéria, morte, sonho, memória e outros mundos. Não é um lugar uniforme, estrada disponível ou reserva de energia.`,evidence:`Relatos de Fraturas mostram repetição espacial, perda desigual de tempo e memórias que deixam efeitos físicos. Tradições associam o fenômeno à Canção do Primeiro Céu, mas a associação não é prova de origem.`,gap:`Espessura, intenção e extensão do Véu permanecem desconhecidas. Nenhum mapa geral ou método seguro de travessia foi registrado.`,dispute:`Teólogos o tratam como limite criado; naturalistas, como propriedade do mundo; ambos descrevem efeitos semelhantes.`,cultural:`Rivs registravam memória, gigantes cantam limites territoriais e Vigias do Limiar priorizam contenção.`,sources:[`Relatórios de Fraturas`,`Canção do Primeiro Céu`,`Protocolos dos Vigias do Limiar`],importance:`Fornece a estrutura comum para portais, Retornados, necromancia e mundos sem reduzir mistério a sistema de viagem conveniente.`,image:`Paisagem dividida por descontinuidade sutil de luz e memória, sem portal decorativo genérico.`,knowledgeStatus:`witnessed`}),"eco-primeiro-ceu":n({overview:`Eco do Primeiro Céu é o nome religioso da mana e lembra que poder hereditário não equivale a propriedade moral. O termo pertence à Doutrina das Três Correntes, não a uma medição científica de origem.`,evidence:`Naturalistas medem efeitos de mana nas três linhagens, mas não detectam um “fragmento” material. Kayler, Nimbus e Rivs preservaram vocabulário convergente antes da perseguição.`,gap:`A origem da mana, o mecanismo hereditário e a razão de existirem somente três Casas continuam desconhecidos.`,dispute:`Devotos leem o Eco literalmente; estudiosos o tratam como metáfora ética para fenômeno real.`,cultural:`O Juramento Arcano usa o termo para limitar autoridade política dos bruxos.`,sources:[`Tratado das Linhagens`,`Juramento Arcano`,`Registros das três Casas`],importance:`Separa fato canônico — hereditariedade — de explicação cosmológica contestada.`,image:`Três recipientes sob céu violeta, efeitos discretos e nenhum diagrama científico conclusivo.`,knowledgeStatus:`disputed`})},c={"fraturas-do-veu":n({overview:`Fraturas são rupturas raras cuja aparência varia conforme lugar e causa; não formam uma rede estável. Toda aproximação exige testemunha, marca de retorno e aceitação de perda possível.`,evidence:`Casos confirmados seguem magia extrema, mortes coletivas, juramentos rompidos ou fenômenos celestes, mas nenhum fator isolado produz abertura previsível.`,gap:`Destino, duração e custo nunca podem ser conhecidos integralmente antes da travessia. Criar Fratura sob comando permanece não registrado.`,dispute:`Facções procuram uma tecnologia repetível; os casos documentados mostram exceções e fracassos.`,cultural:`Vigias cercam sem monumentalizar, enquanto Cartógrafos registram o que muda entre observações.`,sources:[`Protocolos dos Vigias`,`Cadernos de retornados`,`Mapas comparativos`],importance:`Impede transporte cotidiano e faz cada travessia produzir consequência física, memorial ou política.`,image:`Ruptura irregular integrada ao ambiente, com marcos de segurança e escribas em escala humana.`,knowledgeStatus:`witnessed`}),"espelho-de-sal":n({overview:`O Espelho de Sal é uma lâmina de água imóvel no deserto que devolve idades diferentes ao reflexo. As cidades de poço o tratam como risco público, não santuário.`,evidence:`Duas travessias registradas produziram lembranças incompatíveis e alterações de idade não confirmadas por documentação anterior. Marcos de distância permanecem estáveis.`,gap:`Destino do outro lado, diferença temporal real e possibilidade de retorno voluntário são desconhecidos.`,dispute:`Alguns veem outro mundo; outros, efeito de memória e desidratação agravado pelo Véu.`,cultural:`A regra local exige escriba e testemunha, pois nenhuma lembrança isolada basta como prova.`,sources:[`Atas das cidades de poço`,`Depoimentos dos dois retornados`,`Medições dos marcos`],importance:`Une lei comunitária, testemunho e instabilidade temporal em um lugar concreto.`,image:`Lâmina de água em salina com reflexo de idade divergente e marcos de pedra ao redor.`,knowledgeStatus:`witnessed`}),"caminho-das-arvores-ausentes":n({overview:`O Caminho das Árvores Ausentes surge em Sylvaris após certas tempestades violetas e contém espécies sem correspondência conhecida em Avernor.`,evidence:`Folhas recolhidas mantêm anatomia coerente e depois perdem pigmento; sentinelas registram diferenças de estação e distância a cada aparição.`,gap:`Não se sabe se conduz a Elyra, a outro tempo da floresta ou a espaço sem mundo estável. O acesso não é convocável.`,dispute:`Cartógrafos defendem destino externo; alguns Círculos afirmam que a própria floresta está registrando futuros possíveis.`,cultural:`Sylvaris limita coleta e fecha a trilha para impedir exploração de ecossistema desconhecido.`,sources:[`Herbários dos Círculos`,`Diários de sentinelas`,`Mapas sazonais`],importance:`Faz do portal uma questão ecológica e epistemológica, não mero atalho.`,image:`Trilha florestal com botânica sutilmente estrangeira, marcadores élficos e ausência de brilho excessivo.`,knowledgeStatus:`people-only`})},l={elyra:n({overview:`Elyra é descrita como território de luz imóvel, sombras atrasadas e cidades claras sem habitantes visíveis. O Arquivo aceita a existência dos materiais retornados, não uma interpretação única do lugar.`,evidence:`Amostras perdem cor sob o luar de Avernor; três relatos independentes registram sombra persistente e ausência de noite.`,gap:`População, extensão, passagem do tempo e natureza das cidades permanecem desconhecidas.`,dispute:`Peregrinos chamam a luz de preservação; retornados a descrevem como forma de aprisionamento.`,cultural:`Cartógrafos usam Elyra para testar se visão e tempo continuam ligados fora de Avernor.`,sources:[`Amostras descoloridas`,`Três diários de travessia`,`Catálogo de sombras`],importance:`Oferece alteridade sem transformar outro mundo em cenário plenamente explicado.`,image:`Cidade clara vazia sob luz fixa, sombras deslocadas e viajante pequeno em primeiro plano.`,knowledgeStatus:`witnessed`}),morvath:n({overview:`Morvath é uma planície de cinzas que reagem a nomes, luto e calor sem chama observável. Nenhuma fonte prova que as cinzas possuam vontade.`,evidence:`Amostras aquecem ao redor de palavras lembradas e tornam-se inertes em sete dias; documentos próximos perderam termos isolados.`,gap:`Origem da cinza, habitantes e escala das planícies são desconhecidas. Rotas permanentes não foram registradas.`,dispute:`A Corte de Cinza fala em matéria obediente; curadores veem memória contaminante e recusam exploração.`,cultural:`Comunidades de luto proíbem amostras, enquanto facções procuram usá-las para apagamento político.`,sources:[`Relatórios de amostra`,`Depoimentos de retornados`,`Documentos com lacunas`],importance:`Conecta memória material, ética funerária e risco de manipulação sem confirmar doutrina de facção.`,image:`Planície de cinzas aglomerando-se ao redor de inscrições apagadas, sem humanoides de cinza.`,knowledgeStatus:`witnessed`}),naelor:n({overview:`Naelor é chamado Mar sem Margens porque viajantes descrevem água contínua e estrelas sob a quilha. Não há costa, mapa ou horizonte comum entre relatos.`,evidence:`Sal que não se dissolve e instrumentos corroídos de modo incomum retornaram com três grupos.`,gap:`Permanece desconhecido se Naelor é mundo, camada do Mar das Estrelas ou interior de Fratura. Pessoas ou descendências alegadas não são publicamente confirmadas.`,dispute:`Eldemar o trata como mar externo; Cartógrafos recusam classificar antes de uma segunda rota verificável.`,cultural:`Marinheiros usam seus relatos para discutir medo de céu aberto e ausência de margem.`,sources:[`Amostras de sal`,`Diários incompletos`,`Laudos de instrumentos`],importance:`Amplia o imaginário marítimo e preserva a incerteza sobre o destino de travessias Rivs.`,image:`Oceano sem costa com estrelas abaixo da superfície e embarcação desgastada, sem mapa conclusivo.`,knowledgeStatus:`disputed`}),varakh:n({overview:`Varakh contém fortificações e exércitos que repetem preparativos para batalha sem inimigo visível. Armas retiradas do lugar se desfazem ao cruzar o Véu.`,evidence:`Juramentados diferentes descrevem os mesmos pátios, sinais de alarme e marcas de povos não reconhecidos.`,gap:`Oponente, causa da repetição, habitantes conscientes e duração real da guerra não foram registrados.`,dispute:`Veteranos afirmam ter servido décadas; cronistas medem apenas noites em Avernor e não conciliam as escalas.`,cultural:`Ravenhold explora a lenda como prova de disciplina; penitentes a leem como condenação da guerra sem fim.`,sources:[`Depoimentos de Juramentados`,`Esboços de fortificação`,`Resíduos de armas desfeitas`],importance:`Questiona obediência e experiência temporal sem fornecer exército intermundos utilizável.`,image:`Fortaleza preparada para batalha ao amanhecer repetido, fileiras sem inimigo e relógios contraditórios.`,knowledgeStatus:`witnessed`}),"fenda-sem-nome":n({overview:`A Fenda sem Nome é registrada por negações porque descrições extensas perdem palavras diferentes em cada cópia. O Arquivo evita transformá-la em vazio, morte ou escuridão por conveniência.`,evidence:`Comparações entre cópias mostram apagamento textual não uniforme e falha de títulos, mesmo sem contato direto conhecido.`,gap:`Localização, extensão, origem e relação completa com Nar-Khalion são restritas ou desconhecidas no registro público.`,dispute:`Seladores falam em intervalo entre mundos; teólogos, em limite da linguagem. Nenhum grupo possui prova final.`,cultural:`Escribas preservam versões paralelas e registram ausências em vez de reconstruí-las.`,sources:[`Cópias divergentes do mesmo verbete`,`Protocolos de Nar-Khalion publicados`,`Relatórios de apagamento`],importance:`Materializa o limite documental e protege o mistério autoral sem inserir o segredo no JavaScript.`,image:`Arquivo com espaços ausentes e paisagem impossível sugerida por margens, sem representar a entidade oculta.`,knowledgeStatus:`redacted`})},u={vazios:n({overview:`Vazios executam gestos e respostas habituais sem demonstrar continuidade pessoal suficiente. A categoria descreve comportamento, não um novo povo.`,evidence:`Pastores documentam rotinas repetidas, ausência de reconhecimento e reação a lugares familiares.`,gap:`Não se sabe quanto da pessoa permanece nem se toda repetição contém consciência.`,dispute:`Famílias veem sinais de retorno; tribunais recusam atribuir identidade civil somente por hábito.`,cultural:`Ritos priorizam nome, despedida e não coerção do corpo.`,sources:[`Cadernos dos Pastores`,`Depoimentos familiares`,`Atas funerárias`],importance:`Força a distinguir semelhança, memória e pessoa.`,image:`Figura repetindo tarefa doméstica em ambiente silencioso, sem horror gráfico.`,knowledgeStatus:`witnessed`}),lembrantes:n({overview:`Lembrantes preservam uma memória única que orienta todas as ações e pode obscurecer o restante da identidade.`,evidence:`Casos convergem em frase, trajeto ou pessoa repetida; mudanças no cenário não alteram o objetivo.`,gap:`A origem da memória dominante e a presença de outras lembranças são desconhecidas.`,dispute:`Coletores de Nomes tentam completar narrativas; Pastores alertam contra fabricar uma pessoa a partir de fragmento.`,cultural:`Famílias usam objetos cotidianos para oferecer contexto sem forçar resposta.`,sources:[`Registros dos Coletores`,`Observações dos Pastores`,`Relatos familiares`],importance:`Explora memória como vínculo e prisão, não como prova simples de ressurreição.`,image:`Retornado diante de um único objeto lembrado, ambiente com outras memórias fora de foco.`,knowledgeStatus:`witnessed`}),juramentados:n({overview:`Juramentados permanecem ligados a promessa incompleta e às vezes cessam quando a obrigação é reconhecida ou cumprida.`,evidence:`Atas registram redução de atividade após reparação pública, embora nem todo caso responda ao mesmo gesto.`,gap:`Não há forma segura de descobrir o juramento sem contaminar o testemunho.`,dispute:`Governos tentam converter promessa em serviço; tradições funerárias recusam prolongar obrigação de morto.`,cultural:`Ravenhold debate se ordens militares sobrevivem à morte; a maioria dos juristas responde que não.`,sources:[`Atas de reparação`,`Depoimentos de Varakh`,`Direito funerário pós-Marcha`],importance:`Confronta dever, consentimento e exploração institucional dos mortos.`,image:`Soldado morto junto a estandarte abaixado e documento de juramento rasgado, sem glorificação.`,knowledgeStatus:`witnessed`}),"coroados-de-cinza":n({overview:`Coroados de Cinza impõem fragmentos de lembrança a grupos próximos, produzindo consenso aparente e sofrimento compartilhado.`,evidence:`Testemunhas relatam a mesma imagem sem terem vivido o evento; cinza residual reage a nomes de Morvath.`,gap:`Origem, intenção e quantidade de Coroados permanecem desconhecidas.`,dispute:`A Corte de Cinza os chama de soberanos da memória; curadores os classificam como contaminação coletiva.`,cultural:`Comunidades afetadas registram versões separadamente antes de se reunir.`,sources:[`Relatórios de contágio memorial`,`Amostras de cinza`,`Entrevistas isoladas`],importance:`Mostra como memória coletiva pode ser imposta e politicamente explorada.`,image:`Grupo cercado por cinza e imagens divergentes, sem coroa metálica literal.`,knowledgeStatus:`disputed`}),desvelados:n({overview:`Desvelados retornaram por Fraturas e percebem limites que outras pessoas não veem, mas essa percepção não é infalível.`,evidence:`Alguns antecipam mudanças de caminho e repetição espacial; outros reagem a lugares sem anomalia posterior.`,gap:`Não se sabe se a percepção é permanente, trauma ou alteração do Véu.`,dispute:`Vigias os consultam com cautela; facções tentam tratá-los como instrumentos de detecção.`,cultural:`Protocolos exigem descanso, consentimento e confirmação por medidas externas.`,sources:[`Relatórios de travessia`,`Testes dos Vigias`,`Diários pessoais`],importance:`Evita transformar sobreviventes em sensores sem autonomia.`,image:`Pessoa observando limites quase invisíveis num caminho comum, com escriba confirmando medidas.`,knowledgeStatus:`witnessed`}),ecoantes:n({overview:`Ecoantes são presenças sem corpo estável que repetem voz, gesto ou percurso ligados a um local.`,evidence:`Gravações escritas de horários mostram padrões e degradação gradual quando o lugar muda.`,gap:`Identidade, consciência e capacidade de perceber observadores permanecem desconhecidas.`,dispute:`Escuta Ancestral os trata como memória de lugar; necromantes alegam pessoa aprisionada sem prova.`,cultural:`Anões e elfos evitam responder diretamente antes de registrar contexto.`,sources:[`Cadernos de ocorrência`,`Mapas de percurso`,`Protocolos de Escuta`],importance:`Separa fenômeno memorial de comunicação garantida com mortos.`,image:`Vestígio translúcido repetindo um caminho em ruína, observado à distância por cronistas.`,knowledgeStatus:`witnessed`}),devorados:n({overview:`Devorados perderam continuidade reconhecível e exibem respostas atribuídas a presença atraída durante uma ruptura. O termo é descritivo e não prova origem demoníaca.`,evidence:`Casos mostram vocabulário desconhecido, rejeição do próprio nome e alteração física instável após Fratura.`,gap:`A natureza da presença e a possibilidade de libertar a pessoa original são desconhecidas.`,dispute:`Seladores defendem contenção; alguns Pastores insistem em procurar consentimento residual antes de destruir corpos.`,cultural:`O medo produziu execuções indevidas, razão pela qual confirmação exige várias testemunhas.`,sources:[`Relatórios dos Seladores`,`Cadernos dos Pastores`,`Atas de revisão de execuções`],importance:`Cria ameaça extrema sem abolir responsabilidade ética diante da incerteza.`,image:`Silhueta corporal instável atrás de barreira ritual material, sem gore ou iconografia religiosa genérica.`,knowledgeStatus:`redacted`}),"marcha-dos-sem-nome":n({overview:`A Marcha dos Sem-Nome de 742 foi evento histórico no qual apagar nomes de lápides agravou o retorno coletivo em vez de contê-lo.`,evidence:`Atas municipais, listas familiares e registros dos Pastores concordam que restaurar nomes em praça reduziu a marcha.`,gap:`O primeiro retorno e o número exato de participantes não foram registrados de maneira uniforme.`,dispute:`Autoridades antigas atribuíram vitória à força; testemunhos mostram que reconhecimento público foi decisivo.`,cultural:`O episódio fundamenta o direito funerário de preservar nomes e proíbe apagamento administrativo.`,sources:[`Atas de 742`,`Listas de lápides restauradas`,`Memórias dos Pastores`],importance:`Preenche o período pós-Caça e conecta política documental a fenômeno sobrenatural.`,image:`Procissão de mortos diante de praça onde famílias restauram nomes, sem espetáculo de batalha.`,knowledgeStatus:`documented`,chronology:[[`742 d.C.`,`Apagamento`,`Autoridades removem nomes e a marcha cresce.`],[`742 d.C.`,`Restituição pública`,`Famílias pronunciam e reinscrevem nomes; os retornos cessam gradualmente.`]]})},d={necromancia:n({overview:`Necromancia reúne práticas que prendem, fabricam ou manipulam corpo, eco, memória, juramento e fragmentos de identidade. O Arquivo não classifica luto, medicina ou lembrança cultural como necromancia por proximidade temática.`,evidence:`Casos documentados cobram memória, vida, identidade ou estabilidade do Véu; resultados integrais de ressurreição nunca foram registrados.`,gap:`A fronteira entre eco consciente e reprodução de memória permanece desconhecida, razão pela qual consentimento e possibilidade de partida são critérios centrais.`,dispute:`Reinos criminalizam categorias amplas; povos atingidos pela Caça exigem distinguir prática abusiva de rito memorial.`,cultural:`Pastores, anões, elfos, orcs e gigantes mantêm protocolos próprios sem escola universal.`,sources:[`Direito funerário de 742`,`Relatórios dos Pastores`,`Protocolos culturais de Escuta`],importance:`Estabelece limites éticos e custos concretos sem transformar morte em recurso reversível.`,image:`Arquivo funerário, objetos memoriais e sinais de ruptura, sem círculo mágico de escola genérica.`,knowledgeStatus:`documented`}),"costura-de-eco":n({overview:`Costura de Eco ancora uma lembrança em matéria morta e produz respostas influenciadas pelo praticante. Ela não restaura pessoa, consentimento ou contexto.`,evidence:`Comparações cegas mostram que perguntas e expectativas alteram a resposta; tribunais rejeitam esse material como prova.`,gap:`Não se sabe se algum fragmento consciente participa ou se toda resposta é composição memorial.`,dispute:`Interrogadores chamam a técnica de testemunho; juristas e Pastores a classificam como fabricação coerciva.`,cultural:`Famílias afetadas exigem destruição dos suportes e reparação do nome usado.`,sources:[`Testes judiciais`,`Objetos apreendidos`,`Pareceres dos Pastores`],importance:`Impede que informação sobrenatural substitua prova e consentimento.`,image:`Objeto morto costurado a fragmentos de escrita contraditória, com tribunal recusando-o ao fundo.`,knowledgeStatus:`documented`}),"escuta-ancestral":n({overview:`Escuta Ancestral é um conjunto de práticas memoriais que interpreta canto, fogo, pedra e objetos sem afirmar posse do morto. Não concede magia verdadeira.`,evidence:`Protocolos públicos exigem testemunhas, limite de duração e liberdade para encerrar o rito; resultados variam por cultura.`,gap:`Nenhuma prática comprova a presença integral da pessoa lembrada, e versões antigas foram perdidas em guerras.`,dispute:`Inquisidores chamaram toda Escuta de feitiçaria; arquivos culturais demonstram função memorial e social anterior às Casas.`,cultural:`Gigantes cantam território, anões leem marcas de obra, orcs testemunham brasas e elfos cuidam jardins de memória.`,sources:[`Cantos dos Pilares`,`Placas anãs`,`Atas de brasa`,`Jardins de Sylvaris`],importance:`Protege diversidade religiosa e separa memória de necromancia coerciva.`,image:`Quatro práticas culturais em registro comparativo, sem efeitos mágicos visíveis.`,knowledgeStatus:`people-only`})},f={"segunda-ruptura":n({overview:`A Segunda Ruptura é uma interpretação de que o Véu sofrerá nova fratura relacionada às cinco Relíquias. As cópias públicas não explicam mecanismo, intenção ou resultado.`,evidence:`O tema aparece em comentários tardios após diferentes crises do Véu, sempre com redação variável.`,gap:`Relação causal, local e condição são desconhecidos; nenhum arquivo público contém instrução de ativação.`,dispute:`Seladores defendem separação dos objetos; outros leem a reunião como metáfora de cinco responsabilidades.`,cultural:`Facções usam a leitura para justificar posse, razão pela qual o Arquivo preserva apenas o aviso geral.`,sources:[`Comentários proféticos divergentes`,`Relatórios de Fraturas`],importance:`Cria risco narrativo sem revelar o segredo autoral das Relíquias.`,image:`Cinco silhuetas de objetos separadas ao redor de rachadura distante, sem diagrama funcional.`,knowledgeStatus:`redacted`}),"noite-sem-estrelas":n({overview:`A Noite sem Estrelas prevê perda de orientação antes de uma porta sem fechadura. Marinheiros e astrônomos não concordam se fala de céu, instrumentos ou memória.`,evidence:`Trechos aparecem em almanaques após eclipses e nevoeiros, mas nenhuma ocorrência satisfez todas as versões.`,gap:`Data, duração e significado de “porta” permanecem desconhecidos.`,dispute:`Eldemar lê como falha náutica; cultos humanos, como crise moral das Sete Virtudes.`,cultural:`Pilotos transformaram a imagem em protocolo de navegação redundante.`,sources:[`Almanaques de Eldemar`,`Sermões dos Sete Nomes`,`Cópias proféticas`],importance:`Mostra como escatologia altera preparação sem confirmar inevitabilidade.`,image:`Navios sob céu sem referências, instrumentos redundantes em primeiro plano.`,knowledgeStatus:`prophetic`}),"ultimo-inverno":n({overview:`O Último Inverno é a leitura de Winterfeld para um frio no qual nenhum abrigo conseguiria acolher todas as pessoas.`,evidence:`Cantos surgem após fomes e registram falhas de estoque mais do que sinais sobrenaturais.`,gap:`Não existe data, temperatura ou relação confirmada com Vyrasul.`,dispute:`Jarls o usam para ampliar reservas; fanáticos o associam ao dragão, leitura rejeitada.`,cultural:`A Vigília da Última Brasa interpreta o fim como teste de solidariedade, não licença para abandonar estrangeiros.`,sources:[`Cantos de inverno`,`Livros de abrigo`,`Atas da Vigília`],importance:`Converte temor do fim em política concreta de hospitalidade.`,image:`Abrigo setentrional cheio, fila chegando e fogo público preservado, sem dragão messiânico.`,knowledgeStatus:`people-only`}),"despertar-dos-pilares":n({overview:`O Despertar dos Pilares pode significar montanhas em movimento ou cobrança de tratados esquecidos. A segunda leitura orienta a diplomacia gigante.`,evidence:`Cantos territoriais associam avalanche, memória e promessa sem distinguir metáfora de fenômeno.`,gap:`Versos completos são conhecidos apenas por comunidades gigantes e não foram traduzidos integralmente.`,dispute:`Humanos temem destruição física; cantores gigantes enfatizam restituição política.`,cultural:`Cada vale revisa seus tratados durante o Círculo do Degelo.`,sources:[`Cantos do Pilar Norte`,`Tratados com Winterfeld`],importance:`Preserva uma escatologia conhecida por um povo e ligada a território e responsabilidade.`,image:`Gigantes cantando diante de montanhas e marcos de tratado, sem golem de pedra literal.`,knowledgeStatus:`people-only`}),"grande-marcha":n({overview:`A Grande Marcha projeta em escala continental o trauma de 742: todos os mortos privados de nome retornariam juntos.`,evidence:`A interpretação surge depois da Marcha dos Sem-Nome, não em textos comprovadamente anteriores.`,gap:`Não existe sinal verificável de retorno global nem contagem dos nomes apagados.`,dispute:`Pastores a usam como alerta jurídico; pregadores a anunciam como punição inevitável.`,cultural:`Famílias promovem restauração de cemitérios em vez de esperar o evento.`,sources:[`Comentários posteriores a 742`,`Direito funerário`,`Registros de cemitérios`],importance:`Liga fim dos tempos a reparação documental contínua.`,image:`Cemitério sendo restaurado por famílias, sombras ao longe sugeridas sem invasão espetacular.`,knowledgeStatus:`prophetic`}),"queda-primeira-raiz":n({overview:`A Queda da Primeira Raiz é debatida em Sylvaris como morte ecológica, perda de memória comum ou encerramento de uma forma de governo.`,evidence:`Versos variam entre jardins e não formam um texto profético único.`,gap:`Localização literal da Primeira Raiz e relação com o mundo físico são desconhecidas.`,dispute:`Isolacionistas preveem dano externo; reformistas leem aviso contra memória concentrada.`,cultural:`Círculos respondem preservando sementes, testemunhos e decisões distribuídas.`,sources:[`Cantos de jardins memoriais`,`Atas dos Círculos`],importance:`Transforma escatologia élfica em debate sobre ecologia e poder.`,image:`Raiz antiga atravessando arquivo vivo, folhas preservadas por várias mãos.`,knowledgeStatus:`people-only`}),"ultimo-golpe":n({overview:`O Último Golpe anão seria uma obra capaz de selar ou romper o mundo. O verbo “golpear” também significa concluir responsabilidade em dialetos de forja.`,evidence:`Versões aparecem em placas de ofício, com objetos diferentes e sem data.`,gap:`Ferramenta, artífice e obra não estão registrados.`,dispute:`Tradicionalistas esperam gesto final; reformistas veem cada inovação responsável como ensaio.`,cultural:`Os Nove Ecos exigem avaliar consequências antes de qualquer grande escavação.`,sources:[`Placas dos Nove Ecos`,`Cantos da Primeira Forja`],importance:`Liga destino a trabalho material sem conceder magia automática aos anões.`,image:`Forja anã diante de obra incompleta e nove avaliadores, sem explosão arcana.`,knowledgeStatus:`people-only`}),"sete-silencios":n({overview:`Sete Silêncios descreve a perda gradual de linguagens essenciais antes de um silêncio completo. “Linguagem” pode ser idioma, rito, memória ou capacidade de testemunhar.`,evidence:`Sete aparece em tradições diferentes, mas a lista de perdas nunca coincide.`,gap:`Não há ordem, data ou identificação autenticada dos sete elementos.`,dispute:`Coletores de Nomes falam de idiomas; sacerdotes, de virtudes; astrônomos, de sinais celestes.`,cultural:`Arquivos multilíngues usam a profecia para justificar cópias em suportes diversos.`,sources:[`Cópias proféticas regionais`,`Catálogos de línguas perdidas`],importance:`Faz preservação cultural funcionar como resistência prática à fatalidade.`,image:`Sete suportes de escrita, alguns incompletos, preservados por diferentes povos.`,knowledgeStatus:`prophetic`}),"mundo-esquecera-nome":n({overview:`O Dia em que o Mundo Esquecerá seu Nome é a interpretação mais abstrata: realidade perderia memória de si e deixaria de manter relações estáveis.`,evidence:`A formulação aparece apenas em comentários tardios ligados a apagamentos da Fenda sem Nome.`,gap:`“Nome do mundo” não possui definição comum e nenhum sinal exclusivo foi identificado.`,dispute:`Filósofos leem colapso de memória; facções usam a frase para anunciar qualquer mudança que rejeitam.`,cultural:`Escribas respondem mantendo registros cruzados, sem declarar que cópia pode salvar cosmologia.`,sources:[`Comentários sobre a Fenda`,`Cadernos de escribas`],importance:`Une o tema de nome e memória sem tornar uma metáfora em previsão garantida.`,image:`Mapa e códices perdendo apenas rótulos, formas ainda presentes e escribas comparando cópias.`,knowledgeStatus:`prophetic`})},p={"nar-khalion":n({overview:`Nar-Khalion é descrita como prisão cosmológica entre matéria, Véu, Fenda sem Nome e espaço fora do tempo. O fato operacional central é público: nenhuma abertura interna é conhecida.`,evidence:`Relatos convergem em retorno do teletransporte, falha de mapas, enfraquecimento de nomes e selos fortalecidos por tentativas de fuga.`,gap:`Localização, construção, criadores e procedimento externo de acesso são secretos, perdidos ou desconhecidos; o site não publica mecanismo.`,dispute:`Alguns textos chamam a prisão de lugar; outros, de condição aplicada a uma consciência.`,cultural:`Seladores tratam toda profecia sobre portas como possível contaminação e exigem fontes paralelas.`,sources:[`Protocolos públicos de contenção`,`Cópias com apagamentos controlados`],importance:`Mantém a prisão absoluta por dentro e desloca qualquer risco para escolhas externas sem revelar como.`,image:`Espaço carcerário sem porta visível, mapas falhando e selos abstratos, sem representar identidade do prisioneiro.`,knowledgeStatus:`redacted`}),"prisioneiro-sem-nome":n({overview:`O Prisioneiro sem Nome é uma presença contida capaz de alcançar sonhos e apresentar futuros possíveis. Nenhuma fala atribuída a ela deve ser tratada como fonte neutra.`,evidence:`Sonhos separados repetem estruturas e incentivos semelhantes; registros de contenção confirmam a existência da presença, não sua narrativa sobre si.`,gap:`Nome, origem, motivo, forma e história completa são conhecidos apenas fora do registro público ou permanecem desconhecidos.`,dispute:`Cultos o tratam como vítima ou soberano; o Arquivo recusa ambas as simplificações.`,cultural:`Vigias registram efeitos, não conversas integrais, para reduzir propagação de interpretação dirigida.`,sources:[`Relatórios públicos de sonhos`,`Protocolos de contenção`],importance:`Cria antagonismo por manipulação de possibilidades e protege a revelação autoral.`,image:`Presença indistinta atrás de camadas de selo, sem rosto ou iconografia que revele origem.`,knowledgeStatus:`redacted`})},m={"ultimo-violeta":n({overview:`Último Violeta circula em cópias anteriores ao retorno público de Sirius, mas a forma atual recebeu comentários que o associam ao herdeiro Kayler.`,evidence:`Três manuscritos preservam “violeta”, “olhos” e “céu”; apenas dois mencionam tempestade.`,gap:`Sujeito, data e sentido de “último” permanecem desconhecidos.`,dispute:`Kayler pode significar pessoa, linhagem ou cor observada num fenômeno celeste.`,cultural:`Monarquias o usam para vigiar Sirius; estudiosos alertam que interpretação interessada altera risco político.`,sources:[`Códice das Margens`,`Cópia de Winterfeld`,`Comentário dos Vigias`],importance:`Expõe o perigo de converter aparência canônica de Sirius em destino inevitável.`,image:`Manuscrito com pigmento violeta desbotado e céu tempestuoso, sem morte explícita de Sirius.`,knowledgeStatus:`disputed`}),"coroa-vazia":n({overview:`Coroa Vazia descreve uma coroa sem cabeça reunindo reis incapazes de ajoelhar. O texto é político e não comprova retorno da Coroa Una.`,evidence:`Versões do século II aparecem tanto em panfletos monarquistas quanto em sátiras republicanas.`,gap:`A identidade da coroa e o número de reis não são registrados.`,dispute:`Restauracionistas leem soberania futura; opositores, aliança fracassada entre governantes orgulhosos.`,cultural:`Cada crise continental reativa o verso sem produzir consenso.`,sources:[`Panfletos pós-Veyron`,`Sátiras das fortalezas`,`Cópias religiosas`],importance:`Permite que a mesma profecia sirva projetos políticos opostos.`,image:`Coroa vazia sobre mesa de conselho com cadeiras afastadas, sem soberano espectral.`,knowledgeStatus:`disputed`}),"arvore-sem-sombra":n({overview:`Árvore sem Sombra relaciona raiz, chão e ausência de sombra. Sylvaris a conserva como pergunta sobre memória e pertencimento.`,evidence:`Fragmentos élficos usam palavras diferentes para “esquecer” e “desprender”; traduções humanas confundem as duas.`,gap:`Não há árvore identificada, data ou evento único.`,dispute:`Círculos leem crise memorial; madeireiros transformam o verso em autorização de corte, leitura rejeitada.`,cultural:`O debate acompanha políticas de manejo e proteção de jardins memoriais.`,sources:[`Canto élfico fragmentário`,`Traduções humanas`,`Atas dos Círculos`],importance:`Mostra como tradução pode legitimar exploração territorial.`,image:`Árvore viva sob luz difusa sem sombra definida, cercada por tradutores e guardiões.`,knowledgeStatus:`people-only`}),"tres-feras-aladas":n({overview:`Três Feras Aladas fala de três asas, uma ausência e um pouso diante do gelo. A associação aos três dragões é plausível, mas não consta dos versos antigos.`,evidence:`A redação antecede nomes modernos de Vyrasul, Alcarion e Mhazir; copistas posteriores adicionaram desenhos dracônicos.`,gap:`“Asa” pode representar criatura, navio ou estandarte; o pouso não possui data.`,dispute:`Naturalistas rejeitam profecia como método de rastreamento; devotos a tratam como destino dos dragões.`,cultural:`Winterfeld usa o verso para explicar Vyrasul, embora o animal não reconheça a interpretação.`,sources:[`Fragmento sem ilustração`,`Cópias iluminadas tardias`,`Catálogo de dragões`],importance:`Mantém exatamente três dragões conhecidos sem transformar correlação em certeza.`,image:`Três rastros alados, apenas um sobre gelo; espécies não definidas no enquadramento.`,knowledgeStatus:`rumor`}),"ultima-forja":n({overview:`Última Forja afirma que um martelo final decidirá o que permanece inteiro sem produzir arma. Dialetos anões permitem ler “martelo” como conselho de ofício.`,evidence:`Duas placas de Kar-Dûm preservam o núcleo, com verbos diferentes para selar e concluir.`,gap:`Artífice, objeto e momento são desconhecidos.`,dispute:`Tradicionalistas esperam ferramenta; reformistas falam em decisão coletiva diante de uma grande obra.`,cultural:`Os Nove Salões citam o verso ao revisar túneis perigosos.`,sources:[`Placas do Quinto Salão`,`Comentário do Oitavo Golpe`],importance:`Relaciona destino a responsabilidade material sem conceder magia aos anões.`,image:`Martelo de trabalho diante de estrutura rachada e conselho observando, sem arma luminosa.`,knowledgeStatus:`people-only`}),"cicatriz-aberta":n({overview:`Cicatriz Aberta descreve uma ferida no céu causada por mãos que chamam medo de prudência. Clãs orcs a conectam a juramentos quebrados.`,evidence:`Versões de brasa e cópias humanas compartilham “ferida” e “medo”, mas discordam sobre quem age.`,gap:`Nenhuma Fratura específica foi identificada e a data é desconhecida.`,dispute:`Orcs leem perseguição e traição; Seladores veem abertura literal do Véu.`,cultural:`Testemunhas de brasa usam o verso para exigir debate público antes de medidas de exceção.`,sources:[`Cantos de brasa`,`Cópias de Ravenhold`,`Comentários dos Seladores`],importance:`Une memória política orc e risco cosmológico sem culpar um povo inteiro.`,image:`Céu com fissura distante sobre assembleia de brasa, foco nas testemunhas e não em guerra.`,knowledgeStatus:`people-only`}),"mar-acima":n({overview:`Mar Acima diz que o mar navegará sobre as estrelas e a margem pedirá um nome. Eldemar preserva leituras de inundação e passagem.`,evidence:`A ordem das palavras muda entre cópias náuticas; mapas de Naelor adotaram o verso somente depois dos primeiros relatos.`,gap:`Margem, nome e direção do movimento não foram registrados.`,dispute:`Pilotos temem maré extrema; Cartógrafos falam em travessia para Naelor.`,cultural:`O verso incentiva marcação redundante de portos, mas não autoriza expedição cega.`,sources:[`Almanaques de Eldemar`,`Comentários de Naelor`,`Cópias portuárias`],importance:`Faz a linguagem marítima oscilar entre desastre natural e cosmologia.`,image:`Estrelas refletidas sob casco e margem encoberta, sem portal confirmado.`,knowledgeStatus:`disputed`}),"chama-sem-coroa":n({overview:`Chama sem Coroa fala de uma chama que guarda criança ou crianças esquecidas por reis. A associação a Sirius é posterior e culturalmente compreensível.`,evidence:`Cópias Bellatrix antigas preservam plural; a forma singular ganhou circulação após histórias de Normus e Namídia.`,gap:`Nenhuma criança é nomeada e a data do texto original foi perdida.`,dispute:`Biógrafos aplicam a Sirius; vigias lembram que a rede protegeu muitas crianças sem magia.`,cultural:`A tradição rebelde lê “chama” como abrigo coletivo, não pessoa escolhida.`,sources:[`Cópias Bellatrix`,`Cantos da Chama sem Coroa`,`Inventários de abrigo`],importance:`Impede que a sobrevivência de Sirius apague outras vítimas e protetores.`,image:`Fogo público sob coroa quebrada protegendo várias silhuetas infantis, sem identificar sobreviventes.`,knowledgeStatus:`people-only`}),"sete-silencios-profecia":n({overview:`Sete Silêncios enumera sete perdas sem explicar se são nomes, línguas, votos ou figuras celestiais. Nenhuma lista canônica acompanha o verso.`,evidence:`Manuscritos de quatro regiões preservam o número e o verbo desfazer, mas divergem nos substantivos.`,gap:`Identidades, sequência e evento permanecem desconhecidos.`,dispute:`Coletores de Nomes, sacerdotes e estudiosos celestiais propõem listas incompatíveis.`,cultural:`Arquivos usam o texto para justificar diversidade de suportes e traduções.`,sources:[`Quatro cópias regionais`,`Comentários dos Coletores`,`Catálogos celestiais`],importance:`Relaciona profecia a perda cultural sem confirmar cosmologia específica.`,image:`Sete espaços vazios em manuscritos diferentes, comparados por escribas de vários povos.`,knowledgeStatus:`disputed`}),"cinco-reliquias":n({overview:`A Profecia das Cinco Relíquias sobrevive em fragmento deliberadamente incompleto: cinco testemunhos buscam uma porta sem nome. O registro público não descreve resultado, combinação ou forma de ativação.`,evidence:`Catálogos confirmam cinco objetos agrupados por tradição posterior, mas não provam que o verso originalmente se referia a eles.`,gap:`Porta, testemunhos, condição e consequência permanecem secretos, perdidos ou desconhecidos.`,dispute:`Facções identificam “testemunhos” com portadores ou objetos; o Arquivo não confirma nenhuma leitura.`,cultural:`Seladores defendem cautela, enquanto caçadores de relíquias usam a profecia como propaganda.`,sources:[`Fragmento profético público`,`Catálogo das Cinco Relíquias`,`Comentários dos Seladores`],importance:`Preserva o eixo narrativo das Relíquias sem vazar o mecanismo guardado no arquivo do autor.`,image:`Cinco objetos mantidos separados diante de porta abstrata sem inscrições funcionais.`,knowledgeStatus:`secret`}),"porta-sem-fechadura":n({overview:`Porta sem Fechadura exige que alguém deixe o próprio nome do outro lado, segundo o verso. A imagem pode descrever Fratura, Nar-Khalion ou perda de identidade.`,evidence:`A frase aparece em cópias contaminadas por vocabulário posterior dos Retornados.`,gap:`Não existe local autenticado nem instrução prática; qualquer procedimento alegado é baseado em rumor.`,dispute:`Necromantes falam em retorno dos mortos; Vigias falam em advertência contra travessia sem identidade.`,cultural:`Seladores registram a profecia como possível influência do Prisioneiro sem tratá-la como voz confiável.`,sources:[`Cópias pós-Marcha`,`Comentários dos Vigias`,`Relatórios de sonho`],importance:`Conecta nome, porta e risco de manipulação sem entregar um método.`,image:`Umbral sem fechadura e etiqueta de nome deixada do lado oposto, sem abertura de cárcere.`,knowledgeStatus:`rumor`})},h={"medalhao-ultimo-sussurro":n({overview:`O Medalhão do Último Sussurro permite contato apenas com o último eco atribuído a um morto e paga cada pergunta com memória emocional do consulente.`,evidence:`Três consultas documentadas produziram fragmentos verificáveis e perdas pessoais observadas por testemunhas.`,gap:`Criador, localização atual e grau de consciência do eco são desconhecidos.`,dispute:`Necromantes chamam o resultado de pessoa; Pastores o tratam como fragmento sem autoridade.`,cultural:`Comunidades funerárias condenam consulta sem consentimento prévio do falecido.`,sources:[`Relatórios dos Pastores`,`Inventário de necrópole`,`Depoimentos de consulentes`],importance:`Dá custo irreversível à busca por respostas dos mortos.`,image:`Medalhão escuro junto a páginas onde uma memória pessoal desapareceu, sem aparição integral.`,knowledgeStatus:`lost`}),fulgarion:n({overview:`Fulgarion é condutora da tempestade Kayler e herança material de Normus para Sirius. A lâmina não cria magia nem concede sangue arcano.`,evidence:`Forja, reparos e sete canais são verificáveis; manifestações foram registradas com custos crescentes.`,gap:`Função original, efeito integral da sétima manifestação e limite final não constam do registro público.`,dispute:`Seladores a chamam de chave; documentos de forja confirmam apenas uma arma condutora cujo uso evoluiu.`,cultural:`Kar-Dûm valoriza manutenção; cortes humanas preferem narrativas de arma absoluta.`,sources:[`Bainha de reparos`,`Registros de forja`,`Carta de Normus — existência pública`],importance:`Materializa poder hereditário, custo físico e disputa de apropriação sobre Sirius.`,image:`Espada longa com sete canais e reparos visíveis, raios conduzidos sem criar tempestade do nada.`,knowledgeStatus:`secret`}),aelysar:n({overview:`Aelysar permanece sob custódia dos Círculos e será entregue a Elara somente após coroação legítima. Não escolhe soberano sozinho nem cria magia de sangue.`,evidence:`Atas sucessórias e cadeia pública de custódia confirmam seis flechas ligadas a deveres.`,gap:`Função integral do Último Ramo e possibilidade de destruição não são publicadas.`,dispute:`Baladas afirmam que o arco rejeita pretendentes; os Círculos atribuem decisão às instituições e ao consentimento.`,cultural:`Sylvaris o entende como obrigação material da coroa, não prêmio.`,sources:[`Atas dos Círculos`,`Linha de custódia de Aelysar`,`Cantos das Seis Flechas`],importance:`Separa artefato, legitimidade e escolha de Elara.`,image:`Arco guardado em estojo vivo com seis encaixes, Elara distante e sem portar o objeto.`,knowledgeStatus:`secret`}),"varkhael-seryn":n({overview:`Varkhael e Seryn são lâminas separadas que convertem fúria e dor em calor e podem afetar nomes e memória quando reunidas.`,evidence:`Relatos de metal escuro e apagamentos próximos convergem, mas nenhuma cadeia de custódia é completa.`,gap:`Criador, origem, localização de cada lâmina e identidade dos portadores são desconhecidos.`,dispute:`A Corte de Cinza alega possuir Varkhael; nenhuma inspeção independente ocorreu.`,cultural:`Vítimas tratam os apagamentos como violência documental, não façanha bélica.`,sources:[`Catálogos de armas incompletos`,`Registros de nomes ausentes`,`Rumores da Corte de Cinza`],importance:`Relaciona emoção, memória e poder sem validar posse de facção.`,image:`Duas lâminas separadas em arquivos distintos, uma quente e outra pálida, sem portadores identificados.`,knowledgeStatus:`rumor`}),ishara:n({overview:`Ishara transfere dor ou tempo de vida e armazena sofrimento no tecido; nenhuma cura produz ausência de custo.`,evidence:`Curas observadas coincidem com bordados escurecidos e colapso posterior de portadores.`,gap:`Localização, capacidade máxima, criadores e consentimento dos antigos pacientes são desconhecidos.`,dispute:`Alguns curadores veem escolha ética; facções pretendem usar transferência sem consentimento.`,cultural:`Hospitais recusam registrar uma cura sem registrar também quem recebeu o preço.`,sources:[`Relatos de curadores`,`Códices de bordados`,`Laudos de colapso tardio`],importance:`Torna cura poderosa um problema de responsabilidade e distribuição de sofrimento.`,image:`Véu claro com bordados escuros, mãos de curadores registrando custos sem mostrar portador atual.`,knowledgeStatus:`lost`})},g=(e,t,r,i,a,o,s,c=`disputed`)=>n({overview:`${e} aparece em textos anteriores à Coroa Una associado a ${t}. ${r}`,evidence:`As fontes preservam nome, domínio e relação com uma Lança, mas não demonstram divindade, corpo imortal ou intervenção material; ${i.charAt(0).toLocaleLowerCase(`pt-BR`)}${i.slice(1)}`,gap:`Origem, natureza e existência histórica de ${e} permanecem desconhecidas; nenhuma instituição pode alegar representação comprovada.`,dispute:`Há leituras como pessoa antiga, título coletivo, povo desaparecido, função cosmológica ou metáfora ética.`,cultural:a,sources:o,importance:`Mantém ${t.toLowerCase()} como conflito moral e histórico, não como poder religioso automaticamente verdadeiro.`,image:s,knowledgeStatus:c}),_={aureon:g(`Aureon`,`Lei`,`Sua máxima adverte que lei sem misericórdia converte culpa em mecanismo.`,`Selos solares atribuídos a ele pertencem a épocas diferentes.`,`Tribunais usam o nome para defender códigos opostos; reformistas exigem reparação além da sentença.`,[`Fragmentos do Código Solar`,`Selos pré-Averen`,`Comentários jurídicos`],`Figura ambígua diante de balança imperfeita e códices de épocas distintas, sem halo divino.`),myriel:g(`Myriel`,`Memória`,`Os textos perguntam o que deve ser lembrado quando recordar também causa ferida.`,`Inscrições de nomes não provam que uma única autora as compôs.`,`Coletores de Nomes invocam Myriel; famílias lembram que preservar não autoriza expor toda intimidade.`,[`Lâminas de nomes`,`Cantos memoriais`,`Comentários dos Coletores`],`Escriba ou figura coletiva entre nomes preservados e páginas protegidas, natureza não definida.`),kaeloran:g(`Kaeloran`,`Guerra`,`Seu ciclo termina quando alguém se recusa a conquistar uma vitória que perpetuaria a guerra.`,`Armas com seu nome variam em metal e século.`,`Ravenhold o usa como patrono militar; veteranos penitentes destacam a recusa final.`,[`Ciclo da Última Batalha`,`Inventários militares antigos`],`Guerreiro abaixando arma diante de campo vazio, sem exército celestial.`),selenya:g(`Selenya`,`Misericórdia`,`Os versos perguntam quando misericórdia imposta nega justiça às vítimas.`,`Relatos de cura não distinguem rito, medicina e alegoria.`,`Hospitais citam cuidado; governantes já usaram o nome para encerrar julgamentos sem reparação.`,[`Hinos de Ishmeriel`,`Registros hospitalares comentados`],`Figura oferecendo cuidado sob testemunho das vítimas, sem milagre visível.`),tharos:g(`Tharos`,`Tempestade`,`É descrito como força que transforma sem reconhecer títulos ou fronteiras.`,`A semelhança com a magia Kayler não prova parentesco ou origem comum.`,`Cultos tentaram apropriar Normus como avatar; Kayler rejeitava essa leitura.`,[`Cantos dos Sete Céus`,`Comentários Kayler públicos`],`Tempestade natural envolvendo figura minúscula e sem traços de Normus ou Sirius.`),nerathiel:g(`Nerathiel`,`Morte`,`A tradição afirma que a morte encerra posse, mas não consequência.`,`Ícones funerários mudam entre povos e não formam retrato consistente.`,`Pastores usam o princípio contra escravização de Retornados; necromantes o reinterpretam como autoridade sobre o fim.`,[`Hinos funerários`,`Direito pós-Marcha`,`Ícones comparados`],`Figura limiar sem rosto junto a portas funerárias de vários povos, sem ceifador genérico.`),oryndar:g(`Oryndar`,`Limiar`,`Cada fronteira protegeria algo e aprisionaria outra coisa.`,`Marcos atribuídos a Oryndar são construções humanas e anãs de datas diversas.`,`Vigias o citam como advertência, enquanto Seladores radicais usam o nome para justificar isolamento absoluto.`,[`Textos do Limiar`,`Catálogo de marcos`,`Protocolos dos Vigias`],`Guardião ou símbolo diante de vários limiares materiais, identidade deliberadamente ambígua.`)},v=(e,t,r,i,a,o,s,c)=>n({overview:`${e} é atribuída a ${t} por tradição textual, mas nenhuma arma completa foi autenticada pelo Arquivo. Fragmentos, réplicas e emblemas devem ser examinados separadamente.`,evidence:r,gap:i,dispute:a,cultural:o,sources:s,importance:`Oferece um objeto de disputa religiosa, arqueológica e política sem confirmar arsenal divino material.`,image:c,knowledgeStatus:`rumor`}),y={solvaris:v(`Solvaris, Lança do Julgamento`,`Aureon`,`Três pontas de lança solares possuem ligas e medidas incompatíveis; apenas o nome compartilhado é antigo.`,`Original, criador, portadores e função permanecem desconhecidos.`,`Tribunais rivais autenticaram fragmentos diferentes para legitimar sentenças.`,`Juristas críticos tratam a lança como símbolo da responsabilidade de julgar.`,[`Catálogo de pontas solares`,`Códigos regionais`],`Três fragmentos incompatíveis em mesa de arquivo, sem reconstrução enganosa.`),elythra:v(`Elythra, Lança dos Nomes`,`Myriel`,`Uma haste inscrita perde letras ao ser copiada, mas o efeito pode vir de desgaste e escolha de escriba.`,`Não há ponta, cadeia de custódia ou texto integral registrado.`,`Coletores afirmam que a arma devolve nomes; famílias temem exposição indevida.`,`Arquivos usam o mito para debater quem controla memória pública.`,[`Haste fragmentária`,`Cópias divergentes`],`Haste com inscrições incompletas entre fichas de nomes protegidos.`),vharun:v(`Vharun, Lança da Última Batalha`,`Kaeloran`,`Canções descrevem uma arma fincada no solo para encerrar combate, não lançada contra inimigo.`,`Local, metal e batalha histórica são desconhecidos.`,`Generais a chamam de arma decisiva; penitentes, de gesto de recusa.`,`Veteranos lembram Vharun em cerimônias de deposição de armas.`,[`Ciclo de Kaeloran`,`Ritos de veteranos`],`Lança fincada entre dois exércitos que baixam armas, sem vitória gloriosa.`),ishmeriel:v(`Ishmeriel, Lança da Misericórdia`,`Selenya`,`Relatos atribuem ponta sem fio usada para marcar proteção, mas nenhum exemplar foi datado.`,`Forma, materiais e efeito são não registrados.`,`Hospitais falam em insígnia; caçadores de relíquias alegam cura automática.`,`Curadores recusam associar misericórdia a poder sem consentimento.`,[`Hinos hospitalares`,`Inventários contestados`],`Insígnia de haste romba em abrigo de feridos, sem emissão mágica.`),raekhar:v(`Raekhar, Lança dos Sete Céus`,`Tharos`,`Sete sulcos aparecem em cópias tardias, mas nenhuma liga conduz mana Kayler de modo verificável.`,`Original e relação com tempestades são desconhecidos.`,`Falsários vendem a arma como equivalente a Fulgarion; especialistas rejeitam a equivalência.`,`Kayler nunca registraram Raekhar como patrimônio da Casa.`,[`Laudos de réplicas`,`Cantos dos Sete Céus`],`Lança corroída sob tempestade distante, sete sulcos sem eletricidade impossível.`),"mor-aeth":v(`Mor-Aeth, Lança do Último Fôlego`,`Nerathiel`,`Fragmentos funerários descrevem haste deixada fora do túmulo para simbolizar fim da posse.`,`Nenhuma arma material foi localizada.`,`Necromantes alegam que retém o último sopro; Pastores tratam isso como distorção.`,`Ritos públicos usam apenas réplicas sem função sobrenatural.`,[`Hinos funerários`,`Protocolos dos Pastores`],`Haste cerimonial deixada do lado de fora de sepultura, sem alma capturada.`),veyrion:v(`Veyrion, Lança do Limiar`,`Oryndar`,`Marcos em forma de ponta indicam fronteiras antigas, mas pertencem a povos e séculos distintos.`,`Não existe centro, haste ou portador autenticado.`,`Seladores falam em arma que fecha mundos; cartógrafos veem metáfora para marcos.`,`Vigias usam o nome como alerta contra confundir barreira e proteção.`,[`Catálogo de marcos`,`Textos do Limiar`],`Marcos de fronteira diferentes alinhados como lança apenas pela perspectiva, sem objeto completo.`)},b={averen:n({overview:`A Dinastia Averen governou a Coroa Una sem regra sucessória escrita capaz de ordenar os três filhos de Edric.`,evidence:`Genealogia, votos das Doze Legiões e decretos finais confirmam filiação, mas não preferência aceita.`,gap:`Intenção particular de Edric e documentos supostamente nomeando herdeiro estão perdidos ou contestados.`,dispute:`Cada ramo produziu uma leitura retroativa de legitimidade.`,cultural:`Reinos posteriores citam Averen como advertência contra sucessão ambígua.`,sources:[`Genealogia Averen`,`Registros das Legiões`,`Decretos do Ano 0`],importance:`Transforma parentesco em causa política da Grande Guerra.`,image:`Árvore Averen diante de doze estandartes divididos, sem herdeiro destacado como verdadeiro.`,knowledgeStatus:`documented`}),veyron:n({overview:`A Dinastia Veyron derivou legitimidade da conquista e da promessa de reunificação, sem consentimento institucional duradouro.`,evidence:`Censos, marchas militares e impostos comprovam governo entre 101 e 158.`,gap:`Duas uniões posteriores aparecem em documentos contestados e nenhuma reivindicação atual é segura.`,dispute:`Restauracionistas chamam Marcellus de unificador; memórias regionais o registram como tirano.`,cultural:`A Noite das Doze Adagas encerrou governo, não toda descendência biológica.`,sources:[`Genealogia Veyron`,`Censos reais`,`Atas de 158`],importance:`Separa sobrevivência familiar de direito político.`,image:`Árvore Veyron sobre mapa reunificado por linhas militares e selos quebrados.`,knowledgeStatus:`disputed`}),"casa-do-lobo":n({overview:`A Casa do Lobo reina em Winterfeld somente mediante confirmação dos jarls e cumprimento do dever de abrigo. A coroa administra passagens e estoques, mas não possui as comunidades gigantes nem as geleiras de Vyrasul.`,evidence:`Livros de estoque e provas públicas registram confirmações e recusas.`,gap:`Dois intervalos genealógicos perderam nomes no degelo e na nevasca.`,dispute:`Runa possui sangue reconhecido, mas jarls contestam se cumpriu nova Prova do Abrigo.`,cultural:`Vyrasul não participa da sucessão e não legitima a Casa.`,sources:[`Genealogia de Winterfeld`,`Livros de abrigo`,`Atas dos jarls`],importance:`Vincula coroa setentrional a serviço material verificável.`,image:`Selo do lobo junto a celeiro aberto e árvore com lacunas marcadas.`,knowledgeStatus:`documented`}),"casa-arden":n({overview:`A Casa Arden depende das Sete Pontes, dos pactos agrários e das obrigações de dique para converter sangue em governo.`,evidence:`Registros civis mostram suspensões e auditorias mesmo dentro da linha principal.`,gap:`Livros queimados e lavados deixam intervalos nominais explícitos.`,dispute:`A ala expansionista tenta fabricar dívida contra Ilyra; associações rurais contestam o cálculo.`,cultural:`Valoria trata colheita e crédito como limite da coroa, não propriedade dela.`,sources:[`Genealogia Arden`,`Livros das Sete Pontes`,`Cadastros de diques`],importance:`Faz legitimidade depender de economia e reparação pública.`,image:`Leão Arden diante de diques e sete selos civis, árvore com páginas danificadas.`,knowledgeStatus:`documented`}),"casa-corven":n({overview:`A Casa Corven precisa combinar sangue, juramento de serviço e maioria no Senado de Estandartes. A coroa permanece submetida a auditoria civil mesmo quando legiões declaram emergência.`,evidence:`Atas de confirmação mostram que nenhum requisito substitui os demais.`,gap:`Incêndios e anexos selados apagaram trechos genealógicos.`,dispute:`Cassor mobiliza tradição militar, mas apoio à Caça às Bruxas ameaça confirmação.`,cultural:`Veteranos reformistas defendem direito de recusa a ordens criminosas.`,sources:[`Genealogia Corven`,`Atas do Senado`,`Juramentos militares`],importance:`Transforma a sucessão em campo da crise moral de Ravenhold.`,image:`Corvo sobre árvore genealógica interrompida e semicírculo senatorial dividido.`,knowledgeStatus:`documented`}),"mare-alta":n({overview:`A Casa da Maré Alta combina filiação, licença de capitão e voto do Conselho das Marés. Nenhum casamento estrangeiro transfere experiência de navegação ou quita deveres de cais.`,evidence:`Livros de bordo comprovam que parentes sem prova marítima foram preteridos.`,gap:`Duas sequências de nomes se perderam em naufrágios documentais.`,dispute:`Guildas suspeitam de manipulação na futura prova de Taris.`,cultural:`Eldemar considera navegação dever público, não ornamento da realeza.`,sources:[`Genealogia Elmer`,`Licenças de capitão`,`Atas do Conselho`],importance:`Vincula herança ao conhecimento prático e às obrigações portuárias.`,image:`Tridente diante de árvore marcada por marés, licença e conselho de capitães.`,knowledgeStatus:`documented`}),"copa-prateada":n({overview:`A Casa da Copa Prateada oferece descendentes elegíveis, mas os Círculos escolhem quem assume a função real.`,evidence:`Atas de 1203 registram a designação de Elara, mantendo Lyssara e Maeriel elegíveis.`,gap:`Debates internos completos e critérios rituais não são todos públicos.`,dispute:`Cortesãos atribuem a escolha a critérios contraditórios; as atas públicas não preservam a deliberação completa.`,cultural:`Sylvaris separa idade, gênero, parentesco e aptidão de governar.`,sources:[`Genealogia real`,`Atas dos Círculos de 1203`,`Protocolo de Aelysar`],importance:`Registra a designação pública de Elara sem expor os critérios reservados dos Círculos.`,image:`Copa prateada sobre três ramos elegíveis, Elara marcada por selo de 1203 e não por primogenitura.`,knowledgeStatus:`documented`})},x={sylvaris:n({overview:`A sucessão de Sylvaris é escolha dos Círculos entre descendentes elegíveis; Elara está designada desde 1203, mas ainda precisa aceitar e ser coroada.`,evidence:`Atas convergentes registram Aelwen reinante, Elara designada e as irmãs elegíveis.`,gap:`Discussões reservadas dos Círculos não são publicadas integralmente.`,dispute:`As razões completas da designação permanecem restritas; versões cortesãs não são tratadas como prova.`,cultural:`Aelysar permanece custodiado até coroação legítima.`,sources:[`Atas de 1203`,`Genealogia real`,`Linha de custódia de Aelysar`],importance:`Distingue designação, consentimento, coroação e posse de artefato.`,image:`Três ramos diante de círculos concêntricos, Elara designada e arco ainda guardado.`,knowledgeStatus:`documented`}),winterfeld:n({overview:`Winterfeld confirma a Casa do Lobo pelo dever de abrigo, estoque e passagem, e não por sangue isolado.`,evidence:`Jarls registram provas sazonais e podem exigir repetição em crise.`,gap:`O governante atual não é nomeado no arquivo público e lacunas antigas permanecem perdidas.`,dispute:`A reivindicação de Runa depende de nova Prova do Abrigo.`,cultural:`Dragão, casamento e riqueza mineral não substituem confirmação.`,sources:[`Atas dos jarls`,`Livros de abrigo`,`Genealogia de Winterfeld`],importance:`Faz clima e hospitalidade moldarem legitimidade.`,image:`Candidata diante de abrigo e celeiros auditados por jarls, sem Vyrasul como eleitor.`,knowledgeStatus:`documented`}),valoria:n({overview:`Valoria exige filiação, quitação de dívidas agrárias e confirmação das Sete Pontes. A confirmação ocorre diante de livros civis e pode ser suspensa quando diques ou celeiros permanecem em dívida.`,evidence:`Cadastros distinguem dívida privada, pública e fabricada.`,gap:`Auditorias atuais ainda não encerraram todas as alegações contra Ilyra.`,dispute:`A ala expansionista tenta declará-la inapta por recusar guerra preventiva.`,cultural:`Barqueiros e agricultores participam da legitimidade por instituições civis.`,sources:[`Livros das Sete Pontes`,`Cadastros de dívida`,`Genealogia Arden`],importance:`Transforma sucessão em disputa sobre alimento, crédito e serviço.`,image:`Herdeira diante de sete pontes e livros de dívida abertos a auditores.`,knowledgeStatus:`documented`}),ravenhold:n({overview:`Ravenhold exige sangue Corven, juramento militar e voto senatorial cumulativos. Mobilizar uma guarnição antes da confirmação não cria direito e pode constituir ruptura do próprio juramento.`,evidence:`Atas preservam confirmações, suspensões e auditorias de comando.`,gap:`A maioria futura do Senado e lealdade de guarnições são não registradas.`,dispute:`Cassor é pretendente suspenso por apoio público à perseguição.`,cultural:`Veteranos reformistas tentam tornar consciência parte formal do serviço.`,sources:[`Atas do Senado`,`Juramentos das legiões`,`Genealogia Corven`],importance:`Faz a crise sucessória testar reforma institucional após a Caça.`,image:`Pretendente diante de estandartes divididos e ata de suspensão, sem coroação.`,knowledgeStatus:`documented`}),eldemar:n({overview:`Eldemar requer descendência, licença marítima vigente e voto do Conselho das Marés. A prova existe para expor julgamento, liderança e responsabilidade em condições que nenhum salão cortesão consegue simular.`,evidence:`Taris possui condição familiar, mas ainda deve concluir a rota do Arquipélago sem escolta real.`,gap:`Resultado da prova e votos futuros são não registrados.`,dispute:`Guildas temem sabotagem ou auxílio clandestino de contrabandistas.`,cultural:`Casamento estrangeiro não transfere experiência de navegação.`,sources:[`Licenças portuárias`,`Atas do Conselho`,`Genealogia da Maré Alta`],importance:`Distingue direito condicional de capacidade demonstrada.`,image:`Candidato preparando embarcação diante de conselho portuário, rota de brumas ainda aberta.`,knowledgeStatus:`unrecorded`})};export{l as _,i as a,y as c,d,c as f,x as g,u as h,s as i,o as l,h as m,a as n,b as o,m as p,_ as r,f as s,r as t,p as u};